"use client";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormMessage,
  useZodForm,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { LoadingButton } from "@/features/form/submit-button";
import { useI18n } from "@/i18n/provider";
import { resolveActionResult } from "@/lib/actions/actions-utils";
import { useMutation } from "@tanstack/react-query";
import { AlertCircle, CheckCircle } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import { toast } from "sonner";
import { useMemo } from "react";
import { addEmailAction } from "./email.action";
import type { EmailActionSchemaType } from "./email.schema";
import { z } from "zod";

type EmailFormProps = {
  submitButtonLabel?: string;
  successMessage?: string;
};

export const EmailForm = ({
  submitButtonLabel,
  successMessage,
}: EmailFormProps) => {
  const { t } = useI18n();
  const schema = useMemo(
    () =>
      z.object({
        email: z.string().email(t("email.invalid")).toLowerCase(),
      }),
    [t],
  );

  const form = useZodForm({
    schema,
  });

  const submit = useMutation({
    mutationFn: async ({ email }: EmailActionSchemaType) => {
      return resolveActionResult(addEmailAction({ email }));
    },
    onSuccess: () => {
      toast.success(successMessage || t("email.success"));
    },
    onError: () => {
      toast.error(t("common.error"));
    },
  });

  const submitLabel = submitButtonLabel ?? t("email.submit");
  const successLabel = successMessage ?? t("email.success");

  return (
    <AnimatePresence mode="wait">
      {submit.isSuccess ? (
        <motion.div
          key="success"
          initial={{
            height: 0,
            opacity: 0,
          }}
          animate={{
            height: "auto",
            opacity: 1,
          }}
        >
          <Alert variant="success">
            <CheckCircle size={20} />
            <AlertTitle>{successLabel}</AlertTitle>
          </Alert>
        </motion.div>
      ) : (
        <motion.div
          key="form"
          animate={{
            height: "auto",
            opacity: 1,
          }}
          exit={{
            height: 0,
            opacity: 0,
          }}
        >
          <Form
            form={form}
            onSubmit={async (v) => submit.mutate(v)}
            className="flex flex-col gap-4"
            disabled={submit.isPending}
          >
            <div className="flex items-center gap-4">
              <FormField
                control={form.control}
                name="email"
                render={({ field }) => (
                  <FormItem className="relative w-full">
                    <FormControl>
                      <Input
                        className="border-accent-foreground/20 bg-accent focus-visible:ring-foreground py-5 text-lg"
                        placeholder={t("email.placeholder")}
                        {...field}
                      />
                    </FormControl>
                    <FormMessage className="absolute -bottom-5" />
                  </FormItem>
                )}
              />
              <LoadingButton
                size="lg"
                variant="invert"
                loading={submit.isPending}
              >
                {submitLabel}
              </LoadingButton>
            </div>
            {submit.isError && (
              <Alert variant="destructive">
                <AlertCircle size={20} />
                <AlertTitle>{submit.error.message}</AlertTitle>
                <AlertDescription>
                  {t("email.errorDescription")}
                </AlertDescription>
              </Alert>
            )}
          </Form>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

"use client";

import { Typography } from "@/components/nowts/typography";
import { useI18n } from "@/i18n/provider";
import { SectionLayout } from "./section-layout";

export const PainSection = () => {
  const { t, tm } = useI18n();
  const withoutItems = tm<string[]>("landing.pain.without.items") ?? [];
  const withItems = tm<string[]>("landing.pain.with.items") ?? [];

  return (
    <SectionLayout
      variant="card"
      size="base"
      className="flex flex-col items-center justify-center gap-4"
    >
      <div className="flex w-full flex-col items-center gap-3 lg:gap-4 xl:gap-6">
        <Typography variant="h1">{t("landing.pain.title")}</Typography>
        <Typography variant="large">{t("landing.pain.subtitle")}</Typography>
        <div className="flex items-start gap-4 max-lg:flex-col">
          <div className="flex-1 rounded-lg bg-red-500/20 p-4 lg:p-6">
            <Typography variant="h3" className="text-red-500">
              {t("landing.pain.without.title")}
            </Typography>
            <ul className="text-foreground/80 mt-4 ml-4 flex list-disc flex-col gap-2 text-lg">
              {withoutItems.map((item) => (
                <li key={item}>{item}</li>
              ))}
            </ul>
          </div>
          <div className="flex-1 rounded-lg bg-green-500/20 p-4 lg:p-6">
            <Typography variant="h3" className="text-green-500">
              {t("landing.pain.with.title")}
            </Typography>
            <ul className="text-foreground/80 mt-4 ml-4 flex list-disc flex-col gap-2 text-lg">
              {withItems.map((item) => (
                <li key={item}>{item}</li>
              ))}
            </ul>
          </div>
        </div>
      </div>
    </SectionLayout>
  );
};

