    12→import { useSession } from "@/lib/auth-client";
    13→import type { AppAuthPlan } from "@/lib/auth/stripe/auth-plans";
    14→import {
    15→  ADDITIONAL_FEATURES,
    16→  LIMITS_CONFIG,
    17→} from "@/lib/auth/stripe/auth-plans";
    18→import { BILLING_URL } from "@/lib/LINKS";
    19→import { cn } from "@/lib/utils";
    20→import { Clock } from "lucide-react";
    21→import { useAction } from "next-safe-action/hooks";
    22→import { toast } from "sonner";
    23→import { useI18n } from "@/i18n/provider";
    24→import { LoadingButton } from "../form/submit-button";
    25→import { upgradeUserAction } from "./plans.action";
    26→
    27→export function PricingCard({
    28→  plan,
    29→  isYearly,
    30→}: {
    31→  plan: AppAuthPlan;
    32→  isYearly?: boolean;
    33→}) {
    34→  const { locale, t, tm } = useI18n();
    35→  // Get the current user
    36→  const { data: session } = useSession();
    37→
    38→  const { execute: upgradeUser, isPending } = useAction(upgradeUserAction, {
    39→    onSuccess: (result) => {
    40→      if (result.data.url) {
    41→        window.location.href = result.data.url;
    42→      }
    43→    },
    44→    onError: (error) => {
    45→      toast.error(error.error.serverError ?? t("pricingCard.upgradeError"));
    46→    },
    47→  });
    48→
    49→  // Calculate pricing details
    50→  const monthlyPrice = plan.price;
    51→  const yearlyPrice = plan.yearlyPrice ?? plan.price * 12;
    52→  const displayPrice = isYearly ? Math.round(yearlyPrice / 12) : monthlyPrice;
    53→  const originalPrice = isYearly ? monthlyPrice : null;
    54→
    55→  // Calculate discount percentage
    56→  const calculateDiscount = (monthlyPrice: number, yearlyPrice: number) => {
    57→    if (monthlyPrice === 0) return 0;
    58→    const annualCost = monthlyPrice * 12;
    59→    const discount = ((annualCost - yearlyPrice) / annualCost) * 100;
    60→    return Math.round(discount);
    61→  };
    62→
    63→  const discount = calculateDiscount(plan.price, plan.yearlyPrice ?? 0);
    64→  const formatCurrency = (value: number) =>
    65→    new Intl.NumberFormat(locale, {
    66→      style: "currency",
    67→      currency: plan.currency,
    68→      minimumFractionDigits: 0,
    69→      maximumFractionDigits: 0,
    70→    }).format(value);
    71→  const additionalFeatures = tm<
    72→    { label: string; description: string }[]
    73→  >(`plans.additionalFeatures.${plan.name}`) ?? [];
    74→
    75→  return (
    76→    <Card
    77→      className={cn(
    78→        "flex flex-col pb-0 transition-all duration-200 hover:shadow-lg",
    79→        plan.isPopular && "border-primary relative overflow-hidden shadow-md",
    80→      )}
    81→    >
    82→      {plan.isPopular && (
    83→        <div className="absolute top-5 right-0">
    84→          <div className="bg-primary text-primary-foreground rounded-l-full px-4 py-1 text-xs font-semibold">
    85→            {t("pricingCard.mostPopular")}
    86→          </div>
    87→        </div>
    88→      )}
    89→
    90→      <CardHeader className={cn("pb-0")}>
