    95→          {t(`plans.descriptions.${plan.name}`)}
    96→        </CardDescription>
    97→      </CardHeader>
    98→
    99→      <CardContent className="flex-1 pt-6">
   100→        <div className="mb-8">
   101→          <div className="flex items-baseline">
   102→            <span className="text-5xl font-bold tracking-tight">
   103→              {formatCurrency(displayPrice)}
   104→            </span>
   105→            <span className="text-muted-foreground ml-1.5">
   106→              {t("pricingCard.perMonth")}
   107→            </span>
   108→          </div>
   109→
   110→          {isYearly && originalPrice !== null && originalPrice > 0 && (
   111→            <div className="mt-2 flex items-center">
   112→              <span className="text-muted-foreground mr-2 line-through">
   113→                {formatCurrency(originalPrice)} {t("pricingCard.perMonth")}
   114→              </span>
   115→              <Badge
   116→                variant="outline"
   117→                className="border-primary/20 bg-primary/10 text-primary"
   118→              >
   119→                {t("pricingCard.save", { percent: `${discount}%` })}
   120→              </Badge>
   121→            </div>
   122→          )}
   123→
   124→          {isYearly && yearlyPrice > 0 && (
   125→            <p className="text-muted-foreground mt-2 text-sm">
   126→              {t("pricingCard.billedYearly", {
   127→                amount: formatCurrency(yearlyPrice),
   128→              })}
   129→            </p>
   130→          )}
   131→
   132→          {plan.freeTrial && (
   133→            <div className="bg-primary/10 text-primary mt-3 inline-flex items-center rounded-full px-3 py-1 text-sm font-medium">
   134→              <Clock className="mr-1.5 size-3.5" />
   135→              {t("pricingCard.freeTrial", { days: plan.freeTrial.days })}
   136→            </div>
   137→          )}
   138→        </div>
   139→
   140→        <div className="space-y-6">
   141→          <h4 className="text-muted-foreground text-sm font-semibold tracking-wider uppercase">
   142→            {t("pricingCard.includes")}
   143→          </h4>
   144→
   145→          <ul className="space-y-5">
   146→            {/* Generate features from limits object */}
   147→            {Object.entries(plan.limits).map(([key, value]) => {
   148→              const limitConfig =
   149→                LIMITS_CONFIG[key as keyof typeof LIMITS_CONFIG];
   150→
   151→              const Icon = limitConfig.icon;
   152→
   153→              return (
   154→                <li key={key} className="flex items-start">
   155→                  <div className="text-primary mt-0.5 mr-3 size-5 shrink-0">
   156→                    <Icon className="size-5" />
   157→                  </div>
   158→                  <div>
   159→                    <p className="font-medium">
   160→                      {t(`plans.limits.${key}.label`, {
   161→                        value: value as number,
