   166→                    </p>
   167→                  </div>
   168→                </li>
   169→              );
   170→            })}
   171→
   172→            {/* Additional features based on plan */}
   173→            {ADDITIONAL_FEATURES[
   174→              plan.name as keyof typeof ADDITIONAL_FEATURES
   175→            ].map((feature, index) => {
   176→              const Icon = feature.icon;
