    52→  const displayPrice = isYearly ? Math.round(yearlyPrice / 12) : monthlyPrice;
    53→  const originalPrice = isYearly ? monthlyPrice : null;
    54→
    55→  // Calculate discount percentage
    56→  const calculateDiscount = (monthlyPrice: number, yearlyPrice: number) => {
    57→    if (monthlyPrice === 0) return 0;
    58→    const annualCost = monthlyPrice * 12;
    59→    const discount = ((annualCost - yearlyPrice) / annualCost) * 100;
    60→    return Math.round(discount);
    61→  };
