    86→            {t("pricingCard.mostPopular")}
    87→          </div>
    88→        </div>
    89→      )}
    90→
    91→      <CardHeader className={cn("pb-0")}>
    92→        <CardTitle className="text-2xl capitalize">
    93→          {t(`plans.names.${plan.name}`)}
    94→        </CardTitle>
    95→        <CardDescription className="mt-1.5">
    96→          {t(`plans.descriptions.${plan.name}`)}
    97→        </CardDescription>
    98→      </CardHeader>
    99→
   100→      <CardContent className="flex-1 pt-6">
   101→        <div className="mb-8">
   102→          <div className="flex items-baseline">
   103→            <span className="text-5xl font-bold tracking-tight">
   104→              {formatCurrency(displayPrice)}
   105→            </span>
   106→            <span className="text-muted-foreground ml-1.5">
   107→              {t("pricingCard.perMonth")}
   108→            </span>
   109→          </div>
   110→
   111→          {isYearly && originalPrice !== null && originalPrice > 0 && (
