import { enUS, fr, type Locale as DateLocale } from "date-fns/locale";
import { defaultLocale, type Locale as AppLocale } from "@/i18n/config";

const dateLocales: Record<AppLocale, DateLocale> = {
  en: enUS,
  fr,
};

